"Darstellung (A): Material auf Körper ziehen":"Udseende (A): træk materiale på legemer",
"Darstellung auf einen Körper ziehen.":"Træk et udseende på et legeme.",
"Darstellung der Körper":"Visning af legemer",
"Darstellung wird aufbereitet …":"Visningen forberedes …",
"Darstellung zurückgesetzt (vom Material).":"Udseende nulstillet (fra materialet).",
"Darstellung „{0}“ auf {1} Körper angewendet.":"Udseendet „{0}“ anvendt på {1} legemer.",
"Darstellungsqualität":"Visningskvalitet",
"Das Bild konnte nicht gelesen werden.":"Billedet kunne ikke læses.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Billedet ligger som skabelon på planet. Indstil derefter størrelse, placering, drejning og dækningsgrad i egenskabsvinduet (f.eks. bredde efter et kendt mål).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Geometrikernens resultat er ulæseligt",
"Das Ergebnis konnte nicht geschrieben werden":"Resultatet kunne ikke skrives",
"Das Maß muss größer als 0 sein.":"Målet skal være større end 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Nettet forbliver et trekantnet (ikke B-Rep). Redigér under NET: Reparér, Reducér, Udglat, Plansnit … 3D-fræsestrategier i Fremstilling kan bearbejde det direkte.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profilen må ikke skære aksen. En åben linje i skitsen kan tjene som akse.",
"Das Profil mit den jetzigen Werten überschreiben":"Overskriv profilen med de nuværende værdier",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profilet føres langs en linje/polylinje. Tegn helst profilet vinkelret på banens start (f.eks. profil på XZ, bane på XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profilet præges ophøjet eller nedsænket fra skitseplanet.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Råemnet er kassen omkring det valgte legeme (plus tillæg).",
"Das Setup hat keine Operationen.":"Opspændingen har ingen operationer.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Værktøjet fræser i cirkler, hvis midte vandrer langs noten. Det er aldrig i indgreb over hele bredden – det tillader store skæredybder og skåner fræser og spindel. Fræseren bør have omkring 60 % af notbredden.",
"Das Werkzeug schneidet die Fläche nicht":"Værktøjet skærer ikke fladen",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Værktøjet skærer i retning af de valgte flader, indtil det når de angivne overmål.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Værktøjet stikker lodret ned som et bor, række for række, ned til modellen plus overmål. Skærekraften virker langs spindlen: egnet til lange værktøjer, dybe kaviteter og mindre stive maskiner. Værktøjet skal skære over midten.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Værktøjet undgår disse flader under hensyntagen til de angivne sikkerhedsafstande (spændeklør, skruestik).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Værktøjet undgår disse flader, mens det bearbejder nærliggende flader, og overholder sikkerhedsafstandene.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Første Esc afbryder kun værktøjet eller valget – et Esc for meget lukker ikke skitsen",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Dette er ikke et hul (afrunding eller tap) – klik på et huls indvendige væg.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Dette er ikke et hul (cylinderflade) – klik på hullets væg.",
"Das ist keine WerkFab-Design-Datei.":"Dette er ikke en WerkFab-designfil.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Dette er ikke en skrå kant – klik på begge ender af affasningskanten.",
"Datei":"Fil",
"Datei ist keine WerkFab-Einstellungsdatei.":"Filen er ikke en WerkFab-indstillingsfil.",
"Datei konnte nicht geöffnet werden:":"Filen kunne ikke åbnes:",
"Dateiendung":"Filendelse",
