"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Egne genveje: åbn gruppemenuen (▾) i værktøjslinjen, klik på ⋮ ved kommandoen → „Skift tastaturgenvej …“.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Egne mål og noter kan trækkes på arket med musen (målelinjens afstand, henvisningslinjens vinkel, vinkelbuens radius). Klik på to hjørner = længdemål. Klik på en cirkelkant i set ovenfra = diameter (eller radius). Vinkel: først hjørnet, derefter ét punkt på hvert ben. Affasning: begge ender af den skrå kant – giver f.eks. 2×45°. I tekstfeltet efter hvert mål står et tillæg som ±0,1, H7 eller 4×.",
