"Ersetzt den Standard-Kurzbefehl „{0}“.":"Erstatter standardgenvejen „{0}“.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Klik først på fladen på det legeme, der flyttes, derefter på målfladen på det andet legeme. Legemet drejes og flyttes, indtil det første klikpunkt ligger på det andet, og fladerne ligger mod hinanden.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Klik først på kanten på det legeme, der flyttes, derefter på målkanten på det andet legeme. Rette kanter lægges sammenfaldende (midte på midte); ved cirkulære kanter – hul og tap – rettes akserne ind, og centrene føres sammen.",
"Erst ein Setup anlegen.":"Opret først en opspænding.",
