"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Vælg først en skitse eller et konstruktionsplan – så ser Ctrl+8 vinkelret på det.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Opret først et legeme i KONSTRUKTION, eller indsæt et net (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Opret først et legeme i KONSTRUKTION.",
