"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Konturer følger kanten af de mørke flader. Midterlinjen løber midt i stregerne – velegnet til graveringer og stregtegninger. „Linjer, buer og cirkler“ genkender lige kanter, skarpe hjørner, afrundinger og cirkler; „Polylinjer“ følger billedet punkt for punkt. Tilpas derefter om nødvendigt målestokken med „Kalibrér skabelon“ eller „Skalér“.",
