"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Kurver i en skitse på planfladen (på tværs af drejeaksen) med en drevet fræser langs Z (X og C kører sammen; Fanuc: polarinterpolation G12.1). Åbne kurver fræses frem og tilbage. Dybde fra planfladen.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Kurver i en skitse, der ligger langs drejeaksen, vikles om omkredsen og fræses med en drevet fræser, der peger mod aksen (Z og C kører sammen; Fanuc: cylinderinterpolation G7.1). Skitseplanet bestemmer den vinkel, hvor konturen sidder; vandrette stykker i skitsen bliver til buer om emnet. Dybde fra ydre diameter.",
