"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Med støttepunkter løber radius gennem de angivne værdier (position i % af kantlængden). Det beregnes af den store geometrikerne; første gang tager det nogle sekunder at indlæse.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Der kan ikke spåntages med 3D-proben",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Sammenlign med det færdige emne: grøn = på mål, blå = restmateriale, rød = for dyb",
