"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Med en gevindbor bruges kun cyklussen „Gevindskæring“ – en boringscyklus ville knække den",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Med flere tilspændinger fræses gevinddybden i trin, der hver fjerner omtrent lige meget – skåner små gevindfræsere og hårde materialer. Det frie pas kører den sidste bane endnu en gang uden tilspænding.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Med „Boringscyklusser“ i NC-programmet udlæses styringscyklusser (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), ellers udskrevne bevægelser.",
