"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Bearbejd kun det, en større fræser har efterladt i hjørner.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Følg kun de steder på konturen, som en større fræser ikke nåede (indvendige hjørner, snævre steder). Uden ind-/udkørselsbuer, holdestege og slutbearbejdningsgange; kompensation i computeren.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Kun hvor referenceværktøjet ikke kunne nå: flade områder parallelt, stejle områder som vandlinje. Med et værktøj fra listen tæller dets form med – for eksempel hvad en torusfræser efterlader i hulkehlerne.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Kun plane flader kan bruges som skitseplan.",
