"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Not langs drejeaksen (f.eks. spændnot) med en drevet fræser, der peger mod aksen; hovedspindlen holder emnet som C-akse. Notbredde = fræser-Ø. Start/slut Z i model-Z; når noten når til planfladen, kører fræseren ind forfra, ellers dykker den ned ved starten. Dybde fra ydre diameter.",
