"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: ingen udjævningsfunktion udlæst (G5.1 er Fanuc) – indstil Hi-Cut/Super-NURBS på maskinen",
