"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Vikler skitsekurverne om cylinderen: X forbliver X, afstanden på tværs af aksen bliver til en bue på afviklings-Ø (drejning A). Skitsen skal ligge parallelt med A-aksen, f.eks. på et tangentialplan. Der fræses i fast dybde under emnets overflade – til graveringer, skrift og noter rundt om emnet.",
