"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0}: GRBL kender ikke radiuskorrektion (G41/G42) – bane udlæst uden korrektion",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: Nulpunkt Y/Z ligger ikke på drejeaksen A (akse ved Y{1} Z{2}) – ved simultan 4-akset bearbejdning skal nulpunktet lægges på aksen (råemnepunkt midte Y/Z)",
