"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: Postprocessor uden cylinderinterpolation – Z og C kører sammen; tilspændingen gælder så afhængigt af styringen ikke langs banen. Indtast hellere skabelonen „Cylinderinterpolation til/fra“",
